        c = _c;
    }

    function run(uint256 amount) public payable {
        uint256 before = address(this).balance;
        require(before >= amount);

        c.deposit{value: amount}();
        uint256 balBeforeDeposit = c.balances(address(this));
        require(balBeforeDeposit >= amount);

