contract InvMutTest {
    C c;
    constructor(C _c) {
        c = _c;
    }

    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(depositAmount > 0);
        require(withdrawAmount > 0);
        require(withdrawAmount <= depositAmount);
        require(address(this).balance >= depositAmount);

        // Setup: deposit so the caller has a withdrawable balance.
        c.deposit{value: depositAmount}();

        uint256 beforeContractBal = address(c).balance;
        uint256 beforeThisBal = address(this).balance;

        // Deciding call: withdraw.
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state.
        uint256 afterContractBal = address(c).balance;
        uint256 afterThisBal = address(this).balance;

        // General rule: on success, the contract loses exactly withdrawAmount and the test contract gains exactly withdrawAmount.
        // On failure, the balances must be unchanged.
        assert(
            reverted
                ? (afterContractBal == beforeContractBal && afterThisBal == beforeThisBal)
                : (afterContractBal + withdrawAmount == beforeContractBal && afterThisBal == beforeThisBal + withdrawAmount)
        );
    }

    receive() external payable {}
}

